const rows = items.map(item => item.json);

if (rows.length === 0) {
  return [{
    json: {
      error: "No se encontraron datos de partida para analizar."
    }
  }];
}

// Datos generales de la partida (de la primera fila)
const g = rows[0];

let gameText = "Partida: " + g.game_id +  " Inicio: "  + g.started_at + "Fin: " + g.ended_at + "Jugadores máximos: " + g.max_players + "Ganador (player_id relativo): " + g.winner_player  +" Turnos registrados (aprox): " + g.total_turns + " Eventos de la partida (en orden cronológico):";

for (const ev of rows) {
  if (!ev.ts) continue;
  gameText += `- ${ev.ts} | event=${ev.event_type}`;
  if (ev.player_id !== null && ev.player_id !== undefined) {
    gameText += `, player_id=${ev.player_id} | `;
  }
  if (ev.player_name) {
    gameText += `, name=${ev.player_name} | `;
  }
  if (ev.card) {
    gameText += `, card=${ev.card} | `;
  }
  gameText += "  |  ";
}

const question = $input.first().json.question || "Dame un resumen de la partida.";

const systemPrompt ="Eres un analista experto en partidas de UNO. Responde SIEMPRE en español, de forma clara, ordenada y breve.Usa solamente la información de la partida que te doy como contexto";

const userPrompt = " A continuación tienes la información de una partida de UNO, incluyendo datos generales y la lista de eventos en orden cronológico. --- DATOS DE LA PARTIDA --- " + gameText + " --- FIN DATOS --- TAREA: " + question;

return [{
  json: {
    systemPrompt,
    userPrompt,
  },
}];

